using System.Text;
using System.Text.Json;
var root=Path.Combine(Path.GetTempPath(),"AssemblyProjects-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var checks=0;void Check(bool b,string text){if(!b)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}async Task Reject(Func<Task> f,string text){try{await f();}catch(Exception e)when(e is SimRfqIntakeProblem or LibraryBomPermissionException or IOException){Check(true,text);return;}throw new Exception("Expected rejection: "+text);}
JsonElement J(object o)=>JsonSerializer.SerializeToElement(o,SimLibraryBomStore.Json);LibraryPreparation R(object o)=>J(o).GetProperty("record").Deserialize<LibraryPreparation>(SimLibraryBomStore.Json)!;string T(object o)=>J(o).GetProperty("token").GetString()!;string F(object o)=>J(o).GetProperty("sourceFingerprint").GetString()!;
var actor=new SimPersona("fixture","fixture","Fixture","ACTIVE",[],[],true,"test");var viewer=actor with{IsSuperAdmin=false,Permissions=["technical_review.view","assembly_library.view"]};
var metadata=new SimStateMetadata("SIM","fixture",1,1,1,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,1,DateTimeOffset.UtcNow,1,1,1);
var store=new SimRfqIntakeStore(root);var correlation=Guid.NewGuid().ToString();
SimRfqIntakeAssembly A(int n)=>new(n,"PART-"+n,"A",n+10,Guid.NewGuid().ToString(),n==2?"LABOR_ONLY":"MATERIAL_AND_LABOR");
var a=A(1);var b=A(2);var c=A(10);var rows=new[]{a,b,c};
var d1=await store.StageDocument(correlation,"shared.txt",0,new MemoryStream(Encoding.UTF8.GetBytes("shared original")),actor);d1=d1 with{SharedAcrossProjects=true};
var d2=await store.StageDocument(correlation,"b-only.txt",0,new MemoryStream(Encoding.UTF8.GetBytes("B original")),actor);d2=d2 with{SharedAcrossProjects=false,AssemblyProjectIds=[b.ProjectId!]};
var customer=new SimRfqIntakeCustomer("fixture","001","Fixture customer","sim-canonical-customer-directory");
var request=new SimRfqIntakeCreateRequest("NEW_QUOTE_REQUEST",customer,3,rows,"MATERIAL_AND_LABOR",true,[d1,d2],["PRICE","LEAD_TIME"],"Fixture",correlation);
await Reject(()=>store.CreateAsync(request with{Assemblies=[a,b,b]},actor,metadata),"duplicate line/project identities rejected");
await Reject(()=>store.CreateAsync(request with{Assemblies=[a,b,c with{ProjectId=null}]},actor,metadata),"missing child identity rejected");
await Reject(()=>store.CreateAsync(request with{TechnicalFiles=[d1,d2 with{AssemblyProjectIds=[Guid.NewGuid().ToString()]}]},actor,metadata),"foreign file association rejected");
await Reject(()=>store.CreateAsync(request with{TechnicalFiles=[d1,d2 with{SharedAcrossProjects=null,AssemblyProjectIds=null}]},actor,metadata),"unassigned incoming file rejected");
await Reject(()=>store.CreateAsync(request with{Assemblies=[a,b with{Scope=null},c]},actor,metadata),"missing per-project scope rejected");
Check(!File.Exists(Path.Combine(root,"data","rfq-intakes.json")),"failed submissions preserve staging without creating intake");
var created=J(await store.CreateAsync(request,actor,metadata));var parent=created.GetProperty("record").Deserialize<SimRfqIntakeRecord>(SimLibraryBomStore.Json)!;
Check(parent.QuoteComposition=="COMBINED_DEFAULT_EXPLICIT_PARTIAL"&&parent.TechnicalReview is null,"parent correlation has quote preference but no shared technical-review state");
Check(parent.Assemblies.Select(a=>a.ProjectId).SequenceEqual(rows.Select(a=>a.ProjectId)),"permanent project IDs persisted unchanged");
Check(parent.TechnicalFiles[1].AssemblyProjectIds!.Single()==b.ProjectId&&parent.TechnicalFiles[0].SharedAcrossProjects==true,"explicit shared and per-project associations persisted");
Check(J(await store.CreateAsync(request,actor,metadata)).GetProperty("duplicate").GetBoolean(),"retry same intake correlation idempotent");
Check(await store.ReadTechnicalReviewAsync(parent.IntakeId) is null,"legacy parent technical review unavailable for project request");Check((await store.ReadRfqs()).Length==0,"legacy parent RFQ cannot accept multi-assembly request");
await Reject(()=>store.CreateAsync(request with{RequestCorrelationId=Guid.NewGuid().ToString(),TechnicalFilesProvided=false,TechnicalFiles=[]},actor,metadata),"project UUID cannot be reused under another parent");
var prep=new SimLibraryPreparation(root,()=>[],store.PreparationSource,store.OpenDocument);store.PreparationLookup=prep.Find;
var first=await prep.Assessment(parent.IntakeId,1,actor);var second=await prep.Assessment(parent.IntakeId,2,actor);var tenth=await prep.Assessment(parent.IntakeId,10,actor);
Check(R(first).Id!=R(tenth).Id&&R(tenth).DisplayId==parent.IntakeId+".10"&&R(first).DisplayId==parent.IntakeId+".1",".1 and .10 labels and identities remain distinct strings");
Check(J(first).GetProperty("source").GetProperty("files").GetArrayLength()==1&&J(second).GetProperty("source").GetProperty("files").GetArrayLength()==2,"each assessment sees only shared and assigned files");
PreparationCommand Cmd(object v,string action,string[] files)=>new(parent.IntakeId,R(v).LineNumber,T(v),F(v),action,null,"A","A","Prepare this project",files);
await Reject(()=>prep.Assess(Cmd(first,"SEND",[d2.DocumentId!]),actor),"cannot route sibling-only file");
await Reject(()=>prep.Assess(Cmd(first,"SEND",[d1.DocumentId!]),viewer),"view rights cannot route project");
second=await prep.Assess(Cmd(second,"REQUEST_INFORMATION",[d2.DocumentId!]),actor);
first=await prep.Assess(Cmd(first,"SEND",[d1.DocumentId!]),actor);var repeat=await prep.Assess(Cmd(first,"SEND",[d1.DocumentId!]),actor);Check(T(first)==T(repeat),"repeat project routing idempotent");
first=await prep.Work(new(R(first).Id,T(first),"START"),actor);
Check(R(first).Status=="IN_PREPARATION"&&R(await prep.Assessment(parent.IntakeId,2,actor)).Status=="WAITING_FOR_INFORMATION"&&R(await prep.Assessment(parent.IntakeId,10,actor)).Status=="AWAITING_ASSESSMENT","one project advances independently while sibling held and third untouched");
var items=J(await store.ListTechnicalReviewsAsync()).GetProperty("items");Check(items.GetArrayLength()==3&&items.EnumerateArray().Select(i=>i.GetProperty("projectId").GetString()).Distinct().Count()==3,"three independent queue lines");
Check(items.EnumerateArray().Single(i=>i.GetProperty("projectId").GetString()==b.ProjectId).GetProperty("status").GetString()=="WAITING_FOR_INFORMATION","queue displays project-specific hold");
Check(R(first).RequestedScope==a.Scope&&R(second).RequestedScope==b.Scope&&R(first).RequestedQuantity==a.Quantity,"per-project quantity and scope retained in handoff");
var source=await store.PreparationSource(parent.IntakeId);var mutable=source;var isolated=new SimLibraryPreparation(Path.Combine(root,"sibling-fixture"),()=>[],_=>Task.FromResult(mutable),store.OpenDocument);
var ia=await isolated.Assessment(parent.IntakeId,1,actor);var ib=await isolated.Assessment(parent.IntakeId,2,actor);
mutable=mutable with{Assemblies=[c,b with{Quantity=999},a]};Check(F(await isolated.Assessment(parent.IntakeId,1,actor))==F(ia),"sibling quantity change and reorder do not invalidate project A");Check(F(await isolated.Assessment(parent.IntakeId,2,actor))!=F(ib),"own quantity change invalidates own fingerprint");
mutable=source with{Files=[source.Files[0],source.Files[1] with{Name="updated-B.txt"}]};Check(F(await isolated.Assessment(parent.IntakeId,1,actor))==F(ia),"sibling-specific file change does not invalidate A");
mutable=source with{Files=[source.Files[0] with{Name="updated-shared.txt"},source.Files[1]]};Check(F(await isolated.Assessment(parent.IntakeId,1,actor))!=F(ia)&&F(await isolated.Assessment(parent.IntakeId,2,actor))!=F(ib),"shared evidence change invalidates each affected project");
await Reject(()=>isolated.Assess(Cmd(ia,"SEND",[d1.DocumentId!]),actor),"stale shared evidence cannot route");
mutable=source with{Assemblies=[c,b,a]};Check(R(await isolated.Assessment(parent.IntakeId,1,actor)).Id==R(ia).Id&&R(await isolated.Assessment(parent.IntakeId,10,actor)).DisplayId==parent.IntakeId+".10","reordering never renumbers project identities");
first=await prep.Work(new(R(first).Id,T(first),"PROMOTE",d1.DocumentId),actor);Check(R(first).Promoted.Length==1&&R(await prep.Assessment(parent.IntakeId,2,actor)).Promoted.Length==0,"promotion is project-local; sibling evidence not promoted");
var reload=new SimLibraryPreparation(root,()=>[],store.PreparationSource,store.OpenDocument);Check(T(await reload.Assessment(parent.IntakeId,1,actor))==T(first),"project state persists across store reload");
var legacyRequest=request with{AssemblyCount=1,Assemblies=[new(1,"LEGACY","B",5)],TechnicalFilesProvided=false,TechnicalFiles=[],RequestCorrelationId=Guid.NewGuid().ToString()};var legacy=J(await store.CreateAsync(legacyRequest,actor,metadata)).GetProperty("record").Deserialize<SimRfqIntakeRecord>(SimLibraryBomStore.Json)!;
Check(legacy.QuoteComposition is null&&legacy.TechnicalReview is not null&&await store.ReadTechnicalReviewAsync(legacy.IntakeId) is not null,"legacy single assembly keeps current review workflow");Check(!J(legacy).TryGetProperty("quoteComposition",out _)&&!J(legacy.Assemblies[0]).TryGetProperty("projectId",out _),"legacy serialized shape not migrated");
Check((await store.OpenDocument(parent.IntakeId,d1.DocumentId!)).Bytes.SequenceEqual(Encoding.UTF8.GetBytes("shared original")),"intake originals preserved");
Console.WriteLine($"TOTAL {checks} isolated multi-project checks passed.");
